public class Solution {
    public int countDifferentSubsequenceGCDs(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            for (int i = 1; i <= num; ++i) {
                if (num % i == 0) {
                    set.add(i);
                    int j = i;
                    while (j <= num) {
                        set.add(j);
                        j += i;
                    }
                }
            }
        }

        Set<Integer> gcdSet = new HashSet<>();
        for (int x : nums) {
            for (int subx : set) {
                if (subx > x) continue;
                int gcd = getGCD(x, subx);
                if (gcd <= Math.max(x, subx)) {
                    gcdSet.add(gcd);
                }
            }
        }

        return gcdSet.size();
    }

    private static int getGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

