public class Solution {
    public int minSpeedOnTime(int[] dist, double hour) {
        long left = 1;
        long right = (long) 1e9 + 7;
        while (left < right - 1) {
            long mid = left + (right - left) / 2;

            // Calculate total time spent travelling at speed 'mid'
            double doubleTime = calcTime(dist, mid);

            if (doubleTime <= hour) { 
                right = mid;   
            } else {
                left = mid + 1;
            }
        }

        // Check for the case when we need to travel at speed == left
        double doubleTime = calcTime(dist, left);
        return ((int)doubleTime > hour)? -1 : left;
    }

    private double calcTime(int[] dist, long speed) {
        double doubleSpeed = 1.0 * speed;
        double doubleTime = 0;

        for (int i = 0; i < dist.length - 1; i++) {
            doubleTime += ((double)dist[i] + speed - 1) / speed;
        }

        // Calculate the time spent on the last leg of the journey
        doubleTime += (double)dist[dist.length-1]/doubleSpeed;

        return doubleTime;
    }
}

