import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean makeEqual(String[] words) {
        // Calculate total number of strings
        int n = words.length;

        // Initialize a hashmap to count the occurrences of each character in all strings
        Map<Character, Integer> charCount = new HashMap<>();

        for (String word : words) {
            // Count the characters in each string
            for (char c : word.toCharArray()) {
                charCount.put(c, charCount.getOrDefault(c, 0) + 1);
            }
        }

        // Check if the total number of occurrences of each character is divisible by n
        boolean isValid = true;
        int[] counts = new int[26]; // ASCII values for 'a' to 'z'

        for (Map.Entry<Character, Integer> entry : charCount.entrySet()) {
            char c = entry.getKey();
            int count = entry.getValue();

            if ((count % n) != 0) {
                isValid = false;
                break;
            }

            counts[c - 'a'] += count / n; // ASCII values for 'a' to 'z'
        }

        // Check if the current string can be formed by moving characters from other strings
        boolean[] currCounts = new boolean[26];

        for (String word : words) {
            int[] tempCounts = new int[26];

            for (char c : word.toCharArray()) {
                tempCounts[c - 'a'] += 1;
            }

            isValid &= check(currCounts, tempCounts);
        }

        return isValid;
    }

    private boolean check(boolean[] currCounts, int[] counts) {
        for (int i = 0; i < 26; ++i) {
            if ((currCounts[i] && !counts[i]) || (!currCounts[i] && counts[i])) {
                return false;
            }

            currCounts[i] |= counts[i];
        }

        return true;
    }

}

