public class Solution {
    public int reductionOperations(int[] nums) {
        Arrays.sort(nums);
        return reduce(nums);
    }

    private int reduce(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] != nums[i + 1]) {
                count += nums.length - i - 1;
            }
        }
        return count;
    }
}

