public class Solution {
    public int minCost(String s) {
        Stack<Character> stack = new Stack<>();
        int cost = 0;
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '|' || c == '&') {
                stack.push(c);
            } else if (c == ')') {
                while (!stack.isEmpty() && stack.peek() != '(') {
                    char op = stack.pop();
                    if (op == '|') cost++;
                    else cost--;
                }
                stack.pop(); // Remove the '('
            }
        }
        return s.length() - cost;
    }
}

