import java.util.*;

public class Solution {
    int new_val, min_flips;
}

public class Solution {

    public Result minCost(String expression) {
        Stack<Stack<Integer>> stack = new Stack<>();
        return solve(expression, stack);
    }

    private Result solve(String exp, Stack<Stack<Integer>> stack) {
        if (exp.isEmpty()) {
            int val = getVal(stack.pop());
            int minFlips = getMinFlips(val, stack);
            stack.push(new Stack<>());
            return new Result(val, minFlips);
        } else if (Character.isDigit(exp.charAt(0))) {
            Stack<Integer> innerStack = new Stack<>();
            while (!exp.isEmpty() && Character.isDigit(exp.charAt(0))) {
                char ch = exp.charAt(0);
                exp = exp.substring(1);
                innerStack.push(ch - '0');
            }
            stack.peek().push(innerStack);
        } else {
            String op = "" + exp.charAt(0);
            exp = exp.substring(1);
            int val = Integer.MIN_VALUE;
            while (!exp.isEmpty() && !Character.isDigit(exp.charAt(0))) {
                char ch = exp.charAt(0);
                if (ch == '(') {
                    Result result = solve(exp, stack);
                    val = result.new_val;
                    exp = exp.substring(result.minFlips + 1);
                } else if (ch == ')') {
                    break;
                }
                op += ch;
            }
            int new_val = applyOp(val, getVal(stack.pop()), op.charAt(0));
            Result minResult = solve(exp, stack);
            int nMinFlips = getNewMinFlips(minResult.new_val, minResult.min_flips + 1);

            if (new_val > nMinFlips) {
                new_val = nMinFlips;
            }
            if (!stack.isEmpty()) {
                stack.peek().push(new Stack<>());
            }
            return new Result(new_val, Math.max(nMinFlips, minResult.min_flips));
        }
        int val1 = getVal(stack.pop());
        Result result2 = solve(exp, stack);
        int nMinFlips = 0;
        if (val1 > 0 && result2.new_val == 0) {
            nMinFlips += val1 + result2.min_flips;
        } else if (result2.new_val > 0 && val1 == 0) {
            nMinFlips += result2.new_val + result2.min_flips;
        }
        int new_val = applyOp(val1, result2.new_val, getOp(stack.pop()));
        return new Result(new_val, Math.max(nMinFlips, result2.min_flips));
    }

    private Stack<Integer> getInnerStack(Stack<Stack<Integer>> stack) {
        if (stack.isEmpty()) {
            return null;
        }
        Stack<Integer> innerStack = stack.peek();
        stack.pop();
        return innerStack;
    }

    private int applyOp(int val1, int val2, char op) {
        if (op == '&') {
            return val1 & val2;
        } else if (op == '|') {
            return val1 | val2;
        }
        return 0;
    }

    private int getVal(Stack<Integer> stack) {
        if (stack.isEmpty()) {
            return 0;
        }
        Stack<Integer> innerStack = stack.pop();
        int sum = 0;
        while (!innerStack.isEmpty()) {
            sum += innerStack.pop();
        }
        stack.push(innerStack);
        return sum;
    }

    private char getOp(Stack<Stack<Integer>> stack) {
        if (stack.isEmpty()) {
            return 0;
        }
        Stack<Integer> innerStack = stack.peek();
        int top = innerStack.pop();
        innerStack.push(top);
        stack.pop();
        stack.push(innerStack);
        return top < 2 ? '&' : '|';
    }

    private int getMinFlips(int val, Stack<Stack<Integer>> stack) {
        if (stack.isEmpty()) {
            return val;
        }
        Stack<Integer> innerStack = stack.peek();
        int sum = 0;
        while (!innerStack.isEmpty()) {
            sum += innerStack.pop();
        }
        stack.pop();
        stack.push(innerStack);
        return sum == val ? getMinFlips(val, stack) : val + getMinFlips(val, stack);
    }

    private int getNewMinFlips(int new_val, int nMinFlips) {
        if (new_val > 0 && nMinFlips % 2 == 1) {
            return nMinFlips;
        } else if (nMinFlips > 0 && new_val == 0) {
            return nMinFlips + 1;
        }
        return Math.max(new_val, nMinFlips);
    }

    private int getInnerStackSum(Stack<Stack<Integer>> stack) {
        if (stack.isEmpty()) {
            return 0;
        }
        Stack<Integer> innerStack = stack.peek();
        stack.pop();
        int sum = 0;
        while (!innerStack.isEmpty()) {
            sum += innerStack.pop();
        }
        stack.push(innerStack);
        return sum;
    }
}

