import java.util.Stack;

public class Solution {
    public int minFlips;

    public Result(int val, int minFlips) {
        this.minFlips = minFlips;
    }
}

public class Solution {

    public Result minCost(String s) {
        Stack<Character> stack = new Stack<>();
        List<Integer> ones = new ArrayList<>();

        for (char c : s.toCharArray()) {
            if (c == '(' || c == '|' || c == '&') {
                stack.push(c);
            } else if (c == ')') {
                Character top = stack.pop();
                while (!stack.isEmpty() && !Character.isDigit(stack.peek())) {
                    char nextTop = stack.pop();
                    if (nextTop == '|') {
                        switch (top) {
                            case '|':
                                ones.add(0);
                                break;
                            case '&':
                                ones.remove(ones.size() - 1);
                                ones.add(2);
                                break;
                            default:
                                break;
                        }
                    } else if (nextTop == '&') {
                        switch (top) {
                            case '|':
                                ones.add(2);
                                break;
                            case '&':
                                ones.remove(ones.size() - 1);
                                ones.add(0);
                                break;
                            default:
                                break;
                        }
                    }
                }
            } else if (Character.isDigit(c)) {
                ones.add(c - '0');
            }
        }

        int n = ones.size();
        int[] dp = new int[n + 1];

        dp[0] = 0;
        for (int i = 1; i <= n; ++i) {
            if (ones.get(i - 1) == 0 || ones.get(i - 1) == 2) {
                dp[i] = Math.min(dp[i - 1], 1 + dp[i - 1]);
            } else {
                dp[i] = 1 + dp[i - 1];
            }
        }

        return new Result(ones.get(n - 1), dp[n]);
    }
}

