class Solution {
    public int getNumberOfBacklogOrders(int[][] orders) {
        PriorityQueue<int[]> buyQueue = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        PriorityQueue<int[]> sellQueue = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        for (int[] order : orders) {
            if (order[2] == 0) { // Buy
                while (!sellQueue.isEmpty() && sellQueue.peek()[0] <= order[0] && buyQueue.size() < sellQueue.size()) {
                    int[] sell = sellQueue.poll();
                    int minAmount = Math.min(order[1], sell[1]);
                    order[1] -= minAmount;
                    sell[1] -= minAmount;

                    if (sell[1] > 0) {
                        sellQueue.add(sell);
                    }
                }

                if (order[1] > 0) {
                    buyQueue.offer(order);
                }
            } else { // Sell
                while (!buyQueue.isEmpty() && buyQueue.peek()[0] >= order[0] && buyQueue.size() < sellQueue.size()) {
                    int[] buy = buyQueue.poll();
                    int minAmount = Math.min(order[1], buy[1]);
                    order[1] -= minAmount;
                    buy[1] -= minAmount;

                    if (buy[1] > 0) {
                        buyQueue.add(buy);
                    }
                }

                if (order[1] > 0) {
                    sellQueue.offer(order);
                }
            }
        }

        long backlog = 0;
        while (!buyQueue.isEmpty()) {
            int[] buy = buyQueue.poll();
            backlog += buy[1];

            while (!sellQueue.isEmpty() && sellQueue.peek()[0] <= buy[0]) {
                int[] sell = sellQueue.poll();
                int minAmount = Math.min(buy[1], sell[1]);
                buy[1] -= minAmount;
                sell[1] -= minAmount;

                if (sell[1] > 0) {
                    sellQueue.add(sell);
                }
            }

            backlog += buy[1];
        }

        return (int) (backlog % (1000000007));
    }
}

