import java.util.Comparator;

public class Solution {
    public int getNumberOfBacklog(int[][] orders) {
        PriorityQueue<Integer> sellOrder = new PriorityQueue<>(Comparator.comparingInt(o -> o));
        long[] backlog = new long[2];
        for (int[] order : orders) {
            if (order[2] == 0) { // buy
                while (!sellOrder.isEmpty() && sellOrder.peek() <= order[0]) {
                    int temp = sellOrder.poll();
                    int amount = ++backlog[1];
                    backlog[0] = (backlog[0] - amount * temp + order[1] * order[0]) % 1000000007;
                }
                backlog[0] = (backlog[0] + order[1]) % 1000000007;
            } else { // sell
                while (!sellOrder.isEmpty() && sellOrder.peek() >= order[0]) {
                    int temp = sellOrder.poll();
                    int amount = ++backlog[0];
                    backlog[1] = (backlog[1] - amount * temp + order[1] * order[0]) % 1000000007;
                }
                backlog[1] = (backlog[1] + order[1]) % 1000000007;
            }
            if (!sellOrder.isEmpty()) {
                for (int i = sellOrder.size() - 1; i >= 0 && sellOrder.peek() > order[0]; --i) {
                    int temp = sellOrder.poll();
                    long amount = backlog[1];
                    backlog[1] = (backlog[1] - amount * temp + order[1] * order[0]) % 1000000007;
                }
            }
            while (!sellOrder.isEmpty()) {
                sellOrder.add(sellOrder.poll());
            }
            for (int i = 1; i <= order[1]; ++i) {
                sellOrder.offer(order[0]);
            }
        }
        return backlog[0] + backlog[1];
    }
}

