public class Solution {
    public int maxSumMinProduct(int[] nums) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int i = 0; i < nums.length; i++) {
            map.put(nums[i], i);
        }

        long left[] = new long[nums.length];
        long right[] = new long[nums.length];

        Stack<Integer> stack1 = new Stack<>();
        Stack<Integer> stack2 = new Stack<>();

        for (int i = 0; i < nums.length; i++) {
            while (!stack2.isEmpty() && map.get(nums[i]) >= map.get(stack2.peek())) {
                stack2.pop();
            }

            if (!stack2.isEmpty()) {
                right[i] = (long) stack2.peek();
            } else {
                right[i] = -1;
            }

            stack2.push(nums[i]);

            while (!stack1.isEmpty() && map.get(nums[i]) >= map.get(stack1.peek())) {
                stack1.pop();
            }

            if (!stack1.isEmpty()) {
                left[i] = (long) stack1.peek();
            } else {
                left[i] = -1;
            }

            stack1.push(nums[i]);
        }

        long prefix[] = new long[nums.length];
        int sum[] = new int[nums.length];

        for (int i = nums.length - 2; i >= 0; i--) {
            if (right[i] == -1) {
                prefix[i] = sum[i + 1] + nums[i];
            }
            else {
                prefix[i] = sum[i + 1] + (long)(nums[i])*(right[i] + 1);
            }

        }

        for (int i = 1; i < nums.length; i++) {
            if (left[i] == -1) {
                sum[i] = sum[i - 1] + nums[i];
            }
            else {
                sum[i] = sum[i - 1] + (long)(nums[i])*(left[i]);
            }

        }

        long ans = Long.MIN_VALUE;

        for (int i = 0; i < nums.length; i++) {
            if(left[i] == -1 && right[i] !=- 1) {
                ans = Math.max(ans, (long)(nums[i]) * sum[right[i]+1]);
            }
           else if(right[i] == -1 && left[i] != -1){
                ans = Math.max(ans , (long)(nums[i])* prefix[left[i]]);
            }else{
                ans =  Math.max(ans, (long) (nums[i])*(prefix[left[i]]-sum[right[i]+1]));
            }
        }

        return ((int)ans)%1000000007;

    }
}

