public class Solution {
    public int getMinSwaps(String num, int k) {
        char[] chars = num.toCharArray();
        Arrays.sort(chars);
        String sortedNum = new String(chars);

        int n = num.length();
        int[] count = new int[10];
        for (int i = 0; i < n; i++) {
            count[num.charAt(i) - '0']++;
        }

        long[] wonderfulPermutations = getWonderfulPermutations(sortedNum, count);
        return k % n == 0 ? 0 : (int) ((k / n + 1) * (n - getMinSwapsToReachKth(wonderfulPermutations, k)));
    }

    private int getMinSwapsToReachKth(long[] wonderfulPermutations, int k) {
        long target = wonderfulPermutations[k];
        String num = new String(wonderfulPermutations);
        int n = num.length();
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (num.charAt(i) != target % 10) {
                int j = i + 1;
                while (j < n && num.charAt(j) != target % 10) {
                    j++;
                }
                char[] chars = num.toCharArray();
                swap(chars, i, j);
                swaps += j - i;
                num = new String(chars);
            }
            target /= 10;
        }
        return swaps;
    }

    private long[] getWonderfulPermutations(String sortedNum, int[] count) {
        long[] wonderfulPermutations = new long[getFactorial(count[0])];
        int index = 0;
        for (int i = 1; i <= 9; i++) {
            if (count[i] > 0) {
                getWonderfulPermutationsRecursive(sortedNum, count, i, 0, wonderfulPermutations, index);
                index += getFactorial(count[0]) / getFactorial(count[i]);
            }
        }
        return wonderfulPermutations;
    }

    private void getWonderfulPermutationsRecursive(String sortedNum, int[] count, int digit, int start, long[] wonderfulPermutations, int index) {
        if (digit == 10) {
            char[] chars = new char[sortedNum.length()];
            for (int i = 0; i < sortedNum.length(); i++) {
                chars[i] = '0';
            }
            for (int i = 1; i <= 9; i++) {
                while (count[i] > 0) {
                    chars[start++] = (char) ('0' + i);
                    count[i]--;
                }
            }
            wonderfulPermutations[index++] = Long.parseLong(new String(chars));
        } else {
            for (int i = start; i <= sortedNum.length() - count[digit]; i++) {
                if (sortedNum.charAt(i) == digit + '0') {
                    getWonderfulPermutationsRecursive(sortedNum, count, digit + 1, i + 1, wonderfulPermutations, index);
                }
            }
        }
    }

    private long getFactorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    private void swap(char[] chars, int i, int j) {
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
    }
}

