import java.util.*;

class Solution {
    public int getMinSwaps(String num, int k) {
        char[] chars = num.toCharArray();
        Arrays.sort(chars);
        String res = new String(chars);

        List<char[]> tmps = new ArrayList<>();
        int i = 0;
        while (i < Math.pow(10, num.length()) && i < k) {
            tmps.add(getPermutation(num));
            i++;
        }

        char[] charArray = res.toCharArray();
        int swaps = 0;

        for (char[] tmp : tmps) {
            int j = 0;
            while (j < num.length() && tmp[j] == charArray[j]) {
                j++;
            }
            if (j >= num.length()) break;
            int l = j;
            while (l > 0 && tmp[l - 1] == charArray[l + 1]) {
                l--;
            }
            swaps += (num.length() - j) - (l - j);
        }

        return swaps;
    }

    private char[] getPermutation(String num) {
        int n = num.length();
        List<Integer> nums = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            nums.add(num.charAt(i) - '0');
        }
        int[] a = Arrays.stream(nums.toArray(new Integer[n])).mapToInt(Integer::intValue).toArray();

        int[] p = {1, 1};
        for (int i = 2; i <= n; ++i) {
            p[0] = p[0] * i % mod;
        }

        char[] ret = new char[n];
        Arrays.fill(ret, ' ');
        return getPerm(a, 0, a.length - 1, 0, ret);
    }

    private int[] a;
    private char[] res;
    static final long mod = (long) Math.pow(10, 9) + 7;

    private char[] getPerm(int[] a, int l, int r, int dft, char[] ret) {
        if (l == r) {
            ret[dft] = (char) ('0' + a[l]);
            return ret;
        }

        long rd = new Random().nextLong() % p[r] / p[l];
        int j = l + rd;

        while (j >= l && j <= r && (p[j - 1] * mod > (rd * p[l])) || (p[j - l] * mod == p[rd])) {
            --j;
        }

        swap(a, l, j);
        char[] t = getPerm(a, l + 1, r, dft, ret);
        swap(a, l, j);

        return getPerm(a, l + 1, r, (dft == 0 || a[dft] != a[l]) ? dft + 1 : dft, t);
    }

    private void swap(int[] a, int i, int j) {
        if (i != j) {
            a[i] ^= a[j];
            a[j] ^= a[i];
            a[i] ^= a[j];
        }
    }
}

