public class Solution {
    public int getMinSwaps(String num, int k) {
        int n = num.length();
        char[] nums = num.toCharArray();

        // Sort the array
        Arrays.sort(nums);

        int swaps = 0;
        for (int i = 0; i < n && k > 0; i++) {
            while (i >= 1 && nums[i] == nums[i - 1]) {
                i--;
            }
            if (nums[i] != num.charAt(i)) {
                // Swap the current digit and the first occurrence of that digit
                int j;
                for (j = n - 2; j >= i; j--) {
                    if (nums[j] == nums[i]) {
                        break;
                    }
                }

                swap(nums, i, j);

                swaps++;
                k--;
            }
        }
        return swaps;
    }

    private void swap(char[] a, int i, int j) {
        char temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }
}

