public class Solution {
    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        // Flip to make p1 be more closer to left than p2 to right end for convenience
        firstPlayer = Math.min(firstPlayer, n - secondPlayer + 1);
        secondPlayer = Math.max(secondPlayer, n - firstPlayer + 1);

        if (firstPlayer == secondPlayer) {
            return new int[]{0, 0};
        }

        // p2 is in the later half (and has >= p1 distance to the end)
        int[] dp = new int[n];
        for (int i = n - 1; i > firstPlayer - 1; --i) {
            if (secondPlayer <= i + 1) {
                continue;
            }
            // Group C are players between p4 and p2, (c+1)/2 will advance to next round.
            int c = secondPlayer - i - 1;
            dp[i] = Math.max(dp[Math.min(i + c + 1, n - 1)], (c + 1) / 2);
        }

        // p2 is in first half (n odd or even) or exact middle (n odd)
        int[] dp2 = new int[n];
        for (int i = firstPlayer; i < n; ++i) {
            if (secondPlayer <= i + 1) {
                continue;
            }
            // Group C are players between p4 and p2, (c+1)/2 will advance to next round.
            int c = secondPlayer - i - 1;
            dp2[i] = Math.max(dp2[Math.min(i + c + 1, n - 1)], (c + 1) / 2);
        }

        // p1 and p2 must compete in the second round (only two rounds).
        int earliest = Integer.MAX_VALUE;
        for (int i = firstPlayer; i < n; ++i) {
            if (secondPlayer <= i + 1) {
                continue;
            }
            int c = secondPlayer - i - 1;
            if ((c + 1) / 2 == dp[i] && (n - i) % 2 == 0) {
                earliest = Math.min(earliest, 2);
            } else if ((c + 1) / 2 == dp2[i]) {
                earliest = Math.min(earliest, 2);
            }
        }

        // p1 and p2 compete in the first round
        int latest = Integer.MAX_VALUE;
        for (int i = n - 1; i > firstPlayer - 1; --i) {
            if (secondPlayer <= i + 1) {
                continue;
            }
            int c = secondPlayer - i - 1;
            if ((c + 1) / 2 == dp[i] && (n - i) % 2 == 0) {
                latest = Math.min(latest, 1);
            } else if ((c + 1) / 2 == dp2[i]) {
                latest = Math.min(latest, 1);
            }
        }

        return new int[]{earliest, latest};
    }
}

