public class Solution {
    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        firstPlayer--;
        secondPlayer--;

        boolean isOdd = (n & 1) != 0;
        if (isOdd && firstPlayer >= (n + 2) / 2 - 1 && firstPlayer <= secondPlayer) return new int[]{(n + 1) / 2, (n + 1) / 2};
        n = Math.min(n, 20);

        boolean[][] dp = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], false);
        }
        if (isOdd && firstPlayer >= (n + 1) / 2 - 1 && secondPlayer <= (n - 2) / 2) return new int[]{(n + 1) / 2, (n + 1) / 2};
        for (int i = n - 1; i >= 0; i--) {
            if (!dp[i][firstPlayer] && firstPlayer != secondPlayer) {
                dp[i][secondPlayer] = true;
            }
            if (i + 1 < n) {
                int j = Math.min((n + 2 >> 1), Math.max(0, ((n - i << 1) >> 1)));
                for (int k = 0; k <= j; k++) {
                    dp[i][k] |= dp[i + 1][(secondPlayer - firstPlayer + k) % n];
                }
            }
        }
        int min = Integer.MAX_VALUE;
        int max = 0;
        for (int i = 0; i < n; i++) if (dp[0][i]) {
            int countA = i, countB = 0;
            int left = firstPlayer - countA + n;
            int right = secondPlayer - countA + n;
            while (left <= right && !(countA == 0 || countB == (n >> 1))) {
                min = Math.min(min, countA + countB + 2);
                max = Math.max(max, countA + countB + 2);

                if (!isOdd) {
                    int j = Math.min((n + 2 >> 1), Math.max(0, ((right - i << 1) >> 1)));
                    for (int k = 0; k <= j; k++) {
                        if ((i + countB + k) % n >= left && dp[i][countA + k] && !dp[countB + k][secondPlayer]) {
                            min = Math.min(min, countA + countB + 2);
                            max = Math.max(max, countA + countB + 2);
                        }
                    }
                } else {
                    if (i >= right - left) break;
                    int j = Math.min((n + 2 >> 1), Math.max(0, ((right - i << 1) >> 1)));
                    for (int k = 0; k <= j; k++) {
                        if ((i + countB + k) % n >= left && dp[i][countA + k] && !dp[countB + k][(secondPlayer - firstPlayer + i) % n]) {
                            min = Math.min(min, countA + countB + 2);
                            max = Math.max(max, countA + countB + 2);
                        }
                    }
                }

                if (countB == (n >> 1)) break;

                int c = ((i - left) >> 1) + 1;
                dp[countA][countB] |= dp[countA + c][(secondPlayer - firstPlayer + i) % n];
                countB += c;
            }
        }

        return new int[]{min, max};
    }
}

