import java.util.Arrays;

public class Solution {
    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int p1 = firstPlayer;
        int p2 = secondPlayer - 1;
        n--;

        if (p2 > n / 2 + n % 2 || p1 < n / 2 + n % 2) return new int[]{ -1, -1 };

        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);

        for (int i = Math.max(p1 - 1, 0); i <= Math.min(n, p1); i++) {
            int c = n + 2;
            for (int j = Math.max(2 * i - n, p2); j <= Math.min(i + 1, p2); j++) {
                if ((c & 1) == 0) dp[i] = Math.min(dp[i], j);
                c++;
            }
        }

        int earliestRound = 1;
        for (int i = 1; i < n && dp[i - 1] != Integer.MAX_VALUE; i++) {
            if (dp[i] == Integer.MAX_VALUE) continue;
            if (i >= p2 - p1 + 1) break;
            else earliestRound++;
        }

        int latestRound = 1;

        for (int j = n - 1; dp[j] != Integer.MAX_VALUE; j--) {
            if (j <= Math.min(p2, i)) continue;
            latestRound++;
        }

        return new int[]{earliestRound, latestRound};
    }
}

