import java.util.Arrays;
import java.util.Random;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int makeStringSorted(String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;
        for (int i = 0; i < n - 1; i++) {
            if (chars[i] > chars[i + 1]) {
                int j = i;
                while (j < n && chars[j] < chars[i]) {
                    j++;
                }
                swap(chars, i, --j);
                reverse(chars, i + 1, n - 1);
            }
        }
        return getOperationsCount(s, Arrays.toString(chars));
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private void reverse(char[] arr, int start, int end) {
        while (start < end) {
            swap(arr, start++, end--);
        }
    }

    private int getOperationsCount(String s, String t) {
        char[] charsS = s.toCharArray();
        char[] charsT = t.toCharArray();
        Arrays.sort(charsT);
        int count = 0;
        for (int i = 0; i < charsS.length; i++) {
            if (charsS[i] != charsT[i]) {
                count++;
            }
        }
        return count % MOD;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        System.out.println(solution.makeStringSorted("cba"));
        System.out.println(solution.makeStringSorted("aab"));
        System.out.println(solution.makeStringSorted("aaabbbcc"));
    }
}

