public class Solution {

    int MOD = (int) Math.pow(10, 9) + 7;
    public int makeStringSorted(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        int ops = 0;
        for (int i = n - 1; i > 0; i--) {
            if (chars[i] < chars[i - 1]) {
                int j = i;
                while (j < n && chars[j] >= chars[i-1]) j++;
                reverse(chars, i, j-1);
                swap(chars, i - 1, j);
                ops++;
            }
        }
        return ops % MOD;
    }

    private void reverse(char[] arr, int start, int end) {
        while (start < end) {
            char temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;
            start++;
            end--;
        }
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

