public class Solution {
    public int minFlips(String s) {
        int n = s.length();
        int res = Integer.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            String t1 = s.substring(i, n) + s.substring(0, i);
            int cnt1 = 0;
            boolean flag = true;
            for (int j = 0; j < n - 1; j++) {
                if ((t1.charAt(j) == '0' && t1.charAt(j+1) == '0') || 
                    (t1.charAt(j) == '1' && t1.charAt(j+1) == '1')) {
                    flag = false;
                    break;
                }
                cnt1 += (t1.charAt(j) != t1.charAt(j + 1)) ? 1 : 0;
            }

            if (!flag) continue;

            String t2 = s.substring(i, n) + s.substring(0, i);
            int cnt2 = 0;
            for (int j = 0; j < n - 1; j++) {
                cnt2 += (t2.charAt(j) != t2.charAt(j + 1)) ? 1 : 0;
            }

            res = Math.min(res, Math.max(cnt1, cnt2));
        }

        return res;
    }
}

