public class Solution {
    public int minFlips(String s) {
        int n = s.length();
        int windowSize = 0;
        int left = -1, right = -1;
        int res = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if ((i == 0 || s.charAt(i-1) != s.charAt(i)) && i % 2 == 0)
            {
                left = i;
                windowSize++;
            }
            else if (windowSize == 1 && s.charAt(i - 1) == s.charAt(i))
            {
                right = i - 1;
                break;
            }
        }

        while (right + 1 < n) {
            res = Math.min(res, getRes(s.substring(left, right + 2)));
            windowSize++;
            if (s.charAt(right) != s.charAt(right+1)) {
                left = right;
                right++;
            } else
            {
                int k;
                for (k = right + 2; k < n && s.charAt(k-1)==s.charAt(k); k++);
                res = Math.min(res, getRes(s.substring(left, k)));
                left = k - 1;
                break;
            }
        }

        if (n % 2 == 0) return res;

        String lastString=s;
        for (int i=left ;i<=right;i++)
        {
            char c='a';
            if(lastString.charAt(i)==s.charAt(left)) c='b';else c='a';

            int k=i+1;
            while(k<n && s.charAt(k)==c)k++;
            res = Math.min(res, getRes(s.substring(i,k)) + 1);
            lastString=s.substring(0,i)+c+s.substring(i,n);

        }
        if (res == Integer.MAX_VALUE) return -1;

        return res;
    }

    public int getRes(String s)
    {
        int n = s.length();
        int a = 0, b = 0;
        for (int i = 0; i < n; ++i) {
            if(i %2 == 0 && s.charAt(i)=='1')
                a++;
            else if(i%2==1&&s.charAt(i)=='0')a++;
        }
        for(int j=0;j<n;++j)
        {
            if(j%2!=0&&s.charAt(j)=='1')b++;
            else if(j%2==0&&s.charAt(j)=='0')b++;
        }
       return Math.min(a,b);
    }

}

