import java.util.Arrays;

public class Solution {
    public int rearrangeSticks(int n, int k) {
        long MOD = (long) 1e9 + 7;
        if (k == 0 || k > n) return 0;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, 1);
        for (int i = 2; i <= n; ++i) {
            long[] next = new long[i];
            for (int j = 1; j < i; ++j) {
                next[j] += dp[j - 1] * (i - j);
                if (next[j] >= MOD) next[j] -= MOD;
                next[j] %= MOD;
                next[j + 1] += dp[j] * j;
                if (next[j + 1] >= MOD) next[j + 1] -= MOD;
                next[j + 1] %= MOD;
            }
            dp = next;
        }
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i <= n; ++i) {
            if (i > 0) prefixSum[i] += prefixSum[i - 1];
            prefixSum[i] += dp[i];
            if (prefixSum[i] >= MOD) prefixSum[i] -= MOD;
        }
        return (int) prefixSum[k - 1];
    }
}

