public class Solution {
    public int rearrangeSticks(int n, int k) {
        long[] dp = new long[n + 1];
        Arrays.fill(dp, 1);
        for (int i = 2; i <= n; i++) {
            dp[i] = (i - 1) * dp[i - 1];
        }
        return (int)(ModularExponentiation(1, k - 1, 1000000007L) 
                * ModularExponentiation(dp[n], 1000000005, 1000000007L)
                % 1000000007L);
    }

    public long ModularExponentiation(long b, long e, long m) {
        if (e == 0 || b % m == 1 || m == 1) return 1;
        long half = ModularExponentiation(b, e / 2, m);
        if (e % 2 == 0) return (half * half) % m;
        else return ((half * half) % m * b) % m;
    }
}

