public class Solution {
    public int minSwaps(String s) {
        int zeros = 0, ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') {
                ++zeros;
            } else {
                ++ones;
            }
        }

        if (Math.abs(zeros - ones) > 1) return -1;

        int n = s.length();
        int ans = Math.min(zeros, ones);

        for (int i = 0; i < n; ++i) {
            // swap 0 and 1 based on the current number of zeros and ones
            char c = s.charAt(i);
            if ((ones > zeros && c == '1') || (zeros >= ones && c == '0')) {
                --ones;
                ++zeros;
                ans += 1;
                s = s.substring(0, i) + (((c == '1') ? '0' : '1')) + s.substring(i + 1);
            } else if ((ones < zeros && c == '1') || (zeros <= ones && c == '0')) {
                --zeros;
                ++ones;
                ans += 1;
                s = s.substring(0, i) + (((c == '0') ? '1' : '0')) + s.substring(i + 1);
            }
        }

        return n - Math.min(zeros, ones);
    }
}
